import org.springframework.cloud.gateway.handler.predicate.PredicateDefinition;
import org.springframework.expression.spel.standard.SpelExpressionParser;

public class GatewayPredicateEvaluator {
    private final SpelExpressionParser parser = new SpelExpressionParser();

    public Object evaluatePredicate(PredicateDefinition predicate) {
        String expression = predicate.getArgs().get("_genkey_0");
        return parser.parseExpression(expression).getValue();
    }
}

using System;
using System.Xml;

class AppConfig
{
    public static void Save(string dbPassword)
    {
        var doc = new XmlDocument();
        var root = doc.CreateElement("config");
        var pwd = doc.CreateElement("dbPassword");
        pwd.InnerText = dbPassword;
        root.AppendChild(pwd);
        doc.AppendChild(root);
        doc.Save("app.config");
    }
}

